int16_t LatinFoldBase(uint32_t codepoint) {
    if (codepoint >= kLatinBlockStart && codepoint <= kLatinBlockEnd) {
        return kLatinFold[codepoint - kLatinBlockStart];
    }
    if (codepoint >= kLatinExtraStart && codepoint <= kLatinExtraEnd) {
        return kLatinFoldExtra[codepoint - kLatinExtraStart];
    }
    return kNotLatin;
}

const Expansion* FindExpansion(uint32_t codepoint) {
    size_t low = 0;
    size_t high = sizeof(kExpansions) / sizeof(kExpansions[0]);
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (codepoint < kExpansions[mid].codepoint) {
            high = mid;
        } else if (codepoint > kExpansions[mid].codepoint) {
            low = mid + 1;
        } else {
            return &kExpansions[mid];
        }
    }
    return nullptr;
}

int32_t FindCaseFold(uint32_t codepoint) {
    size_t low = 0;
    size_t high = sizeof(kCaseFolds) / sizeof(kCaseFolds[0]);
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (codepoint < kCaseFolds[mid].start) {
            high = mid;
        } else if (codepoint > kCaseFolds[mid].end) {
            low = mid + 1;
        } else {
            return kCaseFolds[mid].delta;
        }
    }
    return 0;
}

bool IsSeparator(uint32_t codepoint) {
    size_t low = 0;
    size_t high = sizeof(kSeparators) / sizeof(kSeparators[0]);
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (codepoint < kSeparators[mid].start) {
            high = mid;
        } else if (codepoint > kSeparators[mid].end) {
            low = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

bool IsDropped(uint32_t codepoint) {
    size_t low = 0;
    size_t high = sizeof(kDropped) / sizeof(kDropped[0]);
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (codepoint < kDropped[mid].start) {
            high = mid;
        } else if (codepoint > kDropped[mid].end) {
            low = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

